/**
 * P2b: V5R1 transfer builder/decoder tests.
 *
 * The address invariant uses a vector generated by packages/crypto-vault itself for the public
 * Hardhat test mnemonic (import with PIN 2580, then getPublicInfo(0)): public key and the
 * testnet/mainnet V5R1 addresses. The builder must reproduce those bytes exactly.
 */
import { describe, it, expect } from 'vitest';
import { Address } from '@ton/core';
import { Buffer as NodeBuffer } from 'buffer';
import {
  v5r1WalletAddress,
  addressRequiresBounce,
  toTestnetDisplayAddress,
  maxTonAmountRaw,
  buildTonTransfer,
  buildJettonTransfer,
  decodeSignedTransfer,
  isTransferStillValid,
  type TransferSigner,
} from './wallet.js';

// Generated from packages/crypto-vault with the public Hardhat test mnemonic and PIN 2580.
const PUBLIC_KEY_HEX = 'c7ead976255c7200c7a161675cc41caa71d08e6211f9e110cc699f65507b9358';
const VAULT_TESTNET_ADDRESS = '0QDZg_XvhyVdOoqQkNKhCWCDg64Q2wXXfHgkGRZyMoT4O_Sc';
const VAULT_MAINNET_RAW = '0:c73162b34cf19667210af3180d6fcfb88df1678cbbbe731f38642534cc6951e4';

/** Decode does not verify signatures; a fixed 64-byte signature is enough for round trips. */
const fakeSigner: TransferSigner = () => Promise.resolve(new Uint8Array(64));

describe('V5R1 wallet id / StateInit invariant', () => {
  it('builder address matches the crypto-vault address byte-for-byte (testnet -3)', () => {
    const built = v5r1WalletAddress(PUBLIC_KEY_HEX, 'testnet');
    expect(built.testnetNonBounceable).toBe(VAULT_TESTNET_ADDRESS);
    expect(
      Address.parse(built.testnetNonBounceable).equals(Address.parse(VAULT_TESTNET_ADDRESS)),
    ).toBe(true);
  });

  it('mainnet address is a different account for the same key (-239)', () => {
    const testnet = v5r1WalletAddress(PUBLIC_KEY_HEX, 'testnet');
    const mainnet = v5r1WalletAddress(PUBLIC_KEY_HEX, 'mainnet');
    expect(Address.parse(mainnet.raw).equals(Address.parse(VAULT_MAINNET_RAW))).toBe(true);
    expect(testnet.raw).not.toBe(mainnet.raw);
    expect(Address.parse(testnet.raw).equals(Address.parse(mainnet.raw))).toBe(false);
  });
});

describe('bounce rules and Max buffer', () => {
  it('maps user-friendly prefixes to the bounce flag', () => {
    expect(addressRequiresBounce(VAULT_TESTNET_ADDRESS)).toBe(false); // 0Q
    expect(addressRequiresBounce('kQ' + VAULT_TESTNET_ADDRESS.slice(2))).toBe(true);
    expect(addressRequiresBounce('UQ' + VAULT_TESTNET_ADDRESS.slice(2))).toBe(false);
    expect(addressRequiresBounce('EQ' + VAULT_TESTNET_ADDRESS.slice(2))).toBe(true);
  });

  it('renders raw addresses as testnet user-friendly forms for review', () => {
    const raw = Address.parse(VAULT_TESTNET_ADDRESS).toRawString();
    expect(toTestnetDisplayAddress(raw, false)).toBe(VAULT_TESTNET_ADDRESS);
    const bounceable = toTestnetDisplayAddress(raw, true);
    expect(bounceable.startsWith('kQ')).toBe(true);
    expect(Address.parse(bounceable).toRawString()).toBe(raw);
    // Unparseable input is returned as-is; the caller fails closed elsewhere.
    expect(toTestnetDisplayAddress('not-an-address', true)).toBe('not-an-address');
  });

  it('reserves a gas buffer from the max TON amount', () => {
    expect(maxTonAmountRaw('1000000000', 50_000_000n)).toBe('950000000');
    expect(maxTonAmountRaw('40000000', 50_000_000n)).toBe('0');
    expect(maxTonAmountRaw('not-a-number', 50_000_000n)).toBe('0');
  });
});

describe('native TON transfer round trip', () => {
  it('builds, signs and decodes back to the exact intent', async () => {
    const validUntil = Math.floor(Date.now() / 1000) + 300;
    const built = await buildTonTransfer(
      {
        publicKeyHex: PUBLIC_KEY_HEX,
        network: 'testnet',
        seqno: 0,
        destination: VAULT_TESTNET_ADDRESS,
        amountRaw: '1000000000',
        bounce: false,
        comment: 'hello ton',
        deploy: true,
        validUntil,
      },
      fakeSigner,
    );
    const decoded = decodeSignedTransfer(built.boc);
    expect(Address.parse(decoded.sender).equals(Address.parse(VAULT_TESTNET_ADDRESS))).toBe(true);
    expect(Address.parse(decoded.recipient).equals(Address.parse(VAULT_TESTNET_ADDRESS))).toBe(
      true,
    );
    expect(decoded.amountRaw).toBe('1000000000');
    expect(decoded.bounce).toBe(false);
    expect(decoded.asset.type).toBe('ton');
    expect(decoded.comment).toBe('hello ton');
    expect(decoded.seqno).toBe(0);
    expect(decoded.validUntil).toBe(validUntil);
    expect(decoded.hasStateInit).toBe(true);
    expect(decoded.messageHash.hex).toMatch(/^[0-9a-f]{64}$/);
    expect(NodeBuffer.from(decoded.messageHash.hex, 'hex').toString('base64')).toBe(
      decoded.messageHash.base64,
    );
    expect(isTransferStillValid(decoded.validUntil)).toBe(true);
  });

  it('uses a 5-minute expiry by default and no StateInit unless deploying', async () => {
    const before = Math.floor(Date.now() / 1000);
    const built = await buildTonTransfer(
      {
        publicKeyHex: PUBLIC_KEY_HEX,
        network: 'testnet',
        seqno: 1,
        destination: VAULT_TESTNET_ADDRESS,
        amountRaw: '1',
        bounce: false,
      },
      fakeSigner,
    );
    expect(built.decoded.validUntil).toBeGreaterThanOrEqual(before + 299);
    expect(built.decoded.validUntil).toBeLessThanOrEqual(before + 302);
    expect(built.decoded.hasStateInit).toBe(false);
  });
});

describe('TEP-74 jetton transfer round trip', () => {
  it('encodes amount/destination/comment in the jetton wallet message', async () => {
    const jettonWallet = v5r1WalletAddress(PUBLIC_KEY_HEX, 'testnet').testnetBounceable;
    const built = await buildJettonTransfer(
      {
        publicKeyHex: PUBLIC_KEY_HEX,
        network: 'testnet',
        seqno: 0,
        jettonWallet,
        destination: VAULT_TESTNET_ADDRESS,
        amountRaw: '5000000',
        comment: 'jetton memo',
        deploy: true,
      },
      fakeSigner,
    );
    const decoded = decodeSignedTransfer(built.boc);
    expect(decoded.asset.type).toBe('jetton');
    const decodedJettonWallet = decoded.asset.jettonWallet;
    expect(decodedJettonWallet).toBeDefined();
    if (decodedJettonWallet) {
      expect(Address.parse(decodedJettonWallet).equals(Address.parse(jettonWallet))).toBe(true);
    }
    expect(Address.parse(decoded.recipient).equals(Address.parse(VAULT_TESTNET_ADDRESS))).toBe(
      true,
    );
    expect(decoded.amountRaw).toBe('5000000');
    expect(decoded.comment).toBe('jetton memo');
    expect(decoded.hasStateInit).toBe(true);
  });
});
